import { Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Switch from "../../ui/base-ui-switch";

// MODEL

export const Model = S.Struct({
  switchModel: Switch.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotSwitchMessage = m("GotSwitchMessage", {
  message: Switch.Message,
});

export const Message = S.Union([GotSwitchMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [switchModel, switchCommands] = Switch.init({
    id: "switch-basic",
  });

  return [
    { switchModel },
    Command.mapMessages(switchCommands, (message) =>
      GotSwitchMessage({ message })
    ),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotSwitchMessage: ({ message }) => {
        const [switchModel, switchCommands] = Switch.update(
          model.switchModel,
          message
        );

        return [
          evo(model, { switchModel: () => switchModel }),
          Command.mapMessages(switchCommands, (message) =>
            GotSwitchMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.switchModel.id,
        model: model.switchModel,
        view: Switch.view,
        viewInputs: {
          toView: (attributes) =>
            h.div(
              [h.Class(Switch.baseUiSwitchRowClassName)],
              [
                h.button(
                  [
                    ...attributes.button,
                    h.Class(Switch.baseUiSwitchButtonClassName),
                  ],
                  [Switch.baseUiSwitchKnob(model.switchModel.isChecked)]
                ),
                h.div(
                  [h.Class(Switch.baseUiSwitchTextClassName)],
                  [
                    h.label(
                      [
                        ...attributes.label,
                        h.Class(Switch.baseUiSwitchLabelClassName),
                      ],
                      ["Notifications"]
                    ),
                    h.p(
                      [
                        ...attributes.description,
                        h.Class(Switch.baseUiSwitchDescriptionClassName),
                      ],
                      ["Receive push notifications."]
                    ),
                  ]
                ),
              ]
            ),
        },
        toParentMessage: (message) => GotSwitchMessage({ message }),
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as BaseUiSwitchBasicExample from "./main";

describe("Base UI switch Basic example", () => {
  test("toggles notification feedback", () => {
    Scene.scene(
      {
        update: BaseUiSwitchBasicExample.update,
        view: BaseUiSwitchBasicExample.view,
      },
      Scene.with(BaseUiSwitchBasicExample.init()[0]),
      Scene.expect(Scene.role("switch", { name: "Notifications" })).toHaveAttr(
        "aria-checked",
        "false"
      ),
      Scene.click(Scene.role("switch", { name: "Notifications" })),
      Scene.expect(Scene.role("switch", { name: "Notifications" })).toHaveAttr(
        "aria-checked",
        "true"
      )
    );
  });
});
